class Solution {
public:
 int largestSubmatrix(vector<vector<int>>& matrix){
  int m=matrix.size(),n=matrix[0].size(),ans=0;vector<int> h(n);
  for(int i=0;i<m;++i){
   for(int j=0;j<n;++j)h[j]=matrix[i][j]?h[j]+1:0;
   vector<int> v=h;sort(v.rbegin(),v.rend());
   for(int j=0;j<n;++j)ans=max(ans,v[j]*(j+1));
  }
  return ans;
 }
};
